"""Build the journal and mobile link hub using the site's editorial templates."""
from pathlib import Path
import runpy
ctx=runpy.run_path(str(Path(__file__).with_name('generate-pages.py')))
page,link,card,cards,image=(ctx[k] for k in ['page','link','card','cards','image'])
articles=[
 ('a-room-in-proportion','A room in proportion.','SPACE / 4 MIN READ','Start with the way you move, then find the piece that belongs.','gallery-niva.webp',[
 ('Begin with everyday life.','Before choosing a silhouette, list what the space needs to do. A reading corner, a conversation area and a dining space each ask different things of a piece. Note the routes between doors and the furniture you already use.'),
 ('Measure the room and the route.','Record the available floor area, door openings and the path into the room. Mark a proposed footprint with removable tape. Walk around it, pull out nearby chairs and check that doors and drawers can still open. A photograph alone cannot tell you how a piece will fit.'),
 ('Compare a few different forms.','A round table introduces a different rhythm from a long rectangular surface. Compare Star and Sintonia in the Room Studio, then try a bench such as Trapézio. Orbit the study and use the isolated view to focus on the outline. Changing the light can help you read the shape, but does not predict the lighting in your actual room.'),
 ('Make the final check with the technical sheet.','The studio is an exploratory tool. Some models use approximate study dimensions; their controls say so. Check the specific size, finish and product variant in its technical document, and confirm any remaining details with the team before ordering.')],'/room-studio/?product=134','Explore Trapézio in the studio'),
 ('materials-in-conversation','Materials in conversation.','MATERIALS / 3 MIN READ','Build a palette through grain, texture and the light around a piece.','material-wood.webp',[
 ('Choose a starting point.','Look for one material already present in your room: the floor, a wall surface or a favorite object. Use that as a reference when comparing furniture finishes. You can look for continuity or introduce a deliberate change in tone and texture.'),
 ('Let each surface play a role.','Wood grain, woven upholstery, glass and metal offer different visual cues. In the collection, Li pairs a wood-veneer top with a stainless-steel base. Plot brings together a solid-wood structure, natural cotton-based weaving and clear glass. Compare the product photographs to see how these materials meet.'),
 ('Look at edges and transitions.','Instead of looking only at the overall color, inspect the junction between a top and its base, the thickness of an edge and the way upholstery meets the frame. Those details often explain the character of a piece more clearly than a distant room photograph.'),
 ('Use digital finishes to explore a direction.','The studio’s wood and textile controls are illustrative palettes, not an availability chart or a color guarantee. Screens, room light and natural variation affect what you see. Request the available finish options and material samples for the exact product before making a final selection.')],'/materials/','Explore the material library'),
 ('reading-a-technical-sheet','Before you choose a piece.','PRODUCT NOTES / 3 MIN READ','A practical guide to using photographs, dimensions and technical documents together.','289-thumb.webp',[
 ('Match the name and version.','Start on the product page and open its technical sheet. Check that the document describes the piece and size you are considering. A collection may include related names or multiple variants; a shared name does not necessarily mean the same footprint.'),
 ('Read every dimension in context.','Width, depth and height describe different parts of a piece. Check the drawing and units, rather than relying on the order of three numbers. For seating, look for seat dimensions where provided. For a table, consider how its base interacts with the chairs or seating beside it.'),
 ('Keep the photograph nearby.','The photograph helps you interpret a drawing: where the supports sit, how the edge is shaped and which areas are upholstered. In the Room Studio, open “Compare with the product photo” while exploring the interactive model. The image remains the reference for details the study may simplify.'),
 ('Resolve missing information before ordering.','If a dimension, material or care instruction is not documented, ask the team. Keep the product name, chosen version and a link to the technical sheet in your enquiry. The contact page prepares an email draft that you can review before sending.')],'/technical-sheets/?product=289&file=1','Read the Sintonia technical sheet')
]
for slug,title,kicker,lead,hero,sections,url,cta in articles:
 body='<article class="journal-article"><p class="note">Uultis digital experience · Editorial guide</p><nav class="article-contents" aria-label="In this article"><span class="eyebrow">IN THIS ARTICLE</span>'+''.join(f'<a href="#section-{i}">{heading}</a>' for i,(heading,_) in enumerate(sections))+'</nav><div class="prose">'+''.join(f'<section id="section-{i}"><h2>{heading}</h2><p>{text}</p></section>' for i,(heading,text) in enumerate(sections))+link(url,cta)+'</div></article><div class="article-back">'+link('/blog/','All journal stories')+'</div>'
 page('blog/'+slug,title,kicker,lead,body,hero)
page('blog','The journal.','IDEAS FOR LIVING','Thoughts on space, materials and the details that make a piece feel at home.','<div class="journal-intro"><p>Take a closer look.</p><span>03 EDITORIAL GUIDES</span></div>'+cards([card(title,kicker+' · '+lead,'/blog/'+slug+'/',hero) for slug,title,kicker,lead,hero,*_ in articles]))
links=[('/#collection','01','Explore the collection','Furniture for your way of living.'),('/room-studio/','02','Enter the 3D Room Studio','Ten pieces. Light, materials and perspective.'),('/blog/','03','Read the journal','Ideas for space and everyday life.'),('/stores/','04','Find a showroom','See the pieces in person.'),('/contact/','05','Start a conversation','Products, finishes and project enquiries.')]
body='<div class="bio-links">'+''.join(f'<a href="{u}"><span class="bio-number">{n}</span><span><strong>{title}</strong><small>{desc}</small></span><span aria-hidden="true">↗</span></a>' for u,n,title,desc in links)+'</div><div class="bio-secondary">'+link('/branding/','Branding')+link('/style-guide/','Style guide')+'</div><nav class="bio-social" aria-label="Social profiles"><a href="https://www.instagram.com/uultis/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.instagram.com/uultis.usa/" target="_blank" rel="noopener">Uultis USA ↗</a></nav>'
page('biolink','Expressions of life.','THE UULTIS WORLD','Brazilian design, in one place. Follow your curiosity.',body)
p=Path('dist/biolink/index.html');s=p.read_text().replace('<body>','<body class="biolink-page">');s=s.replace('<main id="content">','<main id="content"><div class="bio-cover" aria-hidden="true"></div>');p.write_text(s)
print('Generated blog, three articles and biolink.')
